      en:'<svg class="flag" viewBox="0 0 18 12" aria-hidden="true"><rect width="18" height="12" fill="#24488e"/><path d="M0 0 18 12M18 0 0 12" stroke="white" stroke-width="3"/><path d="M0 0 18 12M18 0 0 12" stroke="#d92338" stroke-width="1.1"/><path d="M9 0v12M0 6h18" stroke="white" stroke-width="4"/><path d="M9 0v12M0 6h18" stroke="#d92338" stroke-width="2"/></svg>',
